-- Expanded question set for personalized interviews
-- Run once: psql -U postgres -d ai_mock_interview -f DATABASE/05-expanded-questions.sql

-- Java
INSERT INTO questions (question, topic, difficulty, role, type, expected_answer, key_concepts) VALUES
('Explain the difference between ArrayList and LinkedList in Java.', 'Java', 'Medium', 'Software Engineer', 'Technical', 'ArrayList uses a dynamic array providing O(1) random access but O(n) insertion/deletion in the middle. LinkedList uses a doubly-linked list providing O(1) insertion/deletion but O(n) random access.', 'ArrayList, LinkedList, dynamic array, linked list, time complexity, random access'),
('What are Java Streams and how do they improve code readability?', 'Java', 'Medium', 'Backend Developer', 'Technical', 'Java Streams provide a functional-style API for processing collections. They support operations like filter, map, and reduce, enabling declarative data processing pipelines that are more readable than imperative loops.', 'Streams, functional programming, filter, map, reduce, declarative'),
('What is the difference between abstract classes and interfaces in Java?', 'Java', 'Easy', 'Software Engineer', 'Technical', 'Abstract classes can have state and implemented methods; interfaces define contracts with default methods. A class can implement multiple interfaces but extend only one abstract class.', 'abstract class, interface, multiple inheritance, contracts, default methods'),
('Explain how the JVM garbage collector works.', 'Java', 'Hard', 'Backend Developer', 'Technical', 'The JVM GC uses generational collection with Young (Eden + Survivor) and Old generations. Minor GC collects Young gen, Major GC collects Old gen. Algorithms include G1, ZGC, and Shenandoah.', 'JVM, generational collection, Young generation, Old generation, G1, ZGC'),

-- Python
('What are Python decorators and how do they work?', 'Python', 'Medium', 'Software Engineer', 'Technical', 'Decorators are functions that modify the behavior of other functions. They use the @decorator syntax and work by wrapping the original function, enabling cross-cutting concerns like logging and caching.', 'decorators, higher-order functions, wrapping, @syntax, cross-cutting concerns'),
('Explain the difference between list comprehensions and generator expressions in Python.', 'Python', 'Medium', 'Data Scientist', 'Technical', 'List comprehensions create the entire list in memory. Generator expressions use lazy evaluation, producing values one at a time, which is memory-efficient for large datasets.', 'list comprehension, generator, lazy evaluation, memory efficiency'),
('What is the Global Interpreter Lock (GIL) in Python?', 'Python', 'Hard', 'Backend Developer', 'Technical', 'The GIL is a mutex that protects access to Python objects, preventing multiple threads from executing Python bytecode simultaneously. It limits true parallelism in CPU-bound multi-threaded programs.', 'GIL, mutex, threading, parallelism, CPU-bound'),

-- JavaScript / Frontend
('Explain the event loop in JavaScript.', 'JavaScript', 'Medium', 'Frontend Developer', 'Technical', 'The event loop continuously checks the call stack and task queue. When the stack is empty, it moves callbacks from the queue to the stack. Microtasks (Promises) have priority over macrotasks (setTimeout).', 'event loop, call stack, task queue, microtasks, macrotasks, Promises'),
('What is the Virtual DOM in React and why is it used?', 'React', 'Medium', 'Frontend Developer', 'Technical', 'The Virtual DOM is an in-memory representation of the real DOM. React uses it to batch updates and compute the minimal set of changes (diffing) needed, improving rendering performance.', 'Virtual DOM, diffing, reconciliation, performance, batch updates'),
('Explain React hooks and their advantages over class components.', 'React', 'Easy', 'Frontend Developer', 'Technical', 'Hooks like useState and useEffect let functional components manage state and side effects. They simplify code reuse through custom hooks and eliminate the complexity of class lifecycle methods.', 'useState, useEffect, functional components, custom hooks, lifecycle'),
('What are closures in JavaScript and where are they useful?', 'JavaScript', 'Medium', 'Full Stack Developer', 'Technical', 'A closure is a function that retains access to its outer scope variables even after the outer function returns. They are useful for data privacy, callbacks, and creating factory functions.', 'closure, lexical scope, data privacy, callbacks, factory functions'),

-- Node.js / Backend
('How does Node.js handle concurrent requests with a single thread?', 'Node.js', 'Medium', 'Backend Developer', 'Technical', 'Node.js uses an event-driven, non-blocking I/O model with the libuv library. Async operations are offloaded to the thread pool or OS, and callbacks are queued via the event loop.', 'event-driven, non-blocking I/O, libuv, event loop, thread pool'),
('What is middleware in Express.js and how does it work?', 'Node.js', 'Easy', 'Backend Developer', 'Technical', 'Middleware functions have access to req, res, and next. They execute sequentially in the pipeline, handling tasks like authentication, logging, error handling, and request parsing.', 'middleware, req, res, next, pipeline, authentication, error handling'),
('Explain the difference between SQL and NoSQL databases.', 'Database', 'Easy', 'Full Stack Developer', 'Technical', 'SQL databases are relational with structured schemas and ACID transactions. NoSQL databases are non-relational, offering flexible schemas and horizontal scalability for unstructured data.', 'SQL, NoSQL, relational, schema, ACID, horizontal scaling'),

-- Spring Boot
('What is Spring Boot and how does it differ from the Spring Framework?', 'Spring Boot', 'Easy', 'Backend Developer', 'Technical', 'Spring Boot is an opinionated framework built on top of Spring that provides auto-configuration, embedded servers, and starter dependencies to simplify application setup and deployment.', 'auto-configuration, embedded server, starter dependencies, convention over configuration'),
('How does dependency injection work in Spring Boot?', 'Spring Boot', 'Medium', 'Backend Developer', 'Technical', 'Spring uses IoC container to manage bean lifecycle. Dependencies are injected via constructor, setter, or field injection using @Autowired. This promotes loose coupling and testability.', 'IoC container, bean, @Autowired, constructor injection, loose coupling'),

-- REST / API
('How would you design a RESTful API for a resource with CRUD operations?', 'REST', 'Medium', 'Backend Developer', 'Technical', 'Use HTTP methods: GET for retrieval, POST for creation, PUT/PATCH for updates, DELETE for removal. Use proper status codes, resource-based URLs, and consistent JSON response format.', 'CRUD, HTTP methods, status codes, resource URLs, JSON, stateless'),
('What is the difference between authentication and authorization?', 'Backend', 'Easy', 'Software Engineer', 'Technical', 'Authentication verifies identity (who you are), while authorization determines permissions (what you can do). Common implementations include JWT tokens and role-based access control.', 'authentication, authorization, JWT, RBAC, identity, permissions'),

-- Database
('Explain database indexing and when you would use it.', 'Database', 'Medium', 'Backend Developer', 'Technical', 'Indexes are data structures (typically B-trees) that speed up data retrieval at the cost of slower writes and additional storage. Use them on frequently queried columns and foreign keys.', 'index, B-tree, data retrieval, query optimization, foreign keys'),
('What is database normalization and what are its normal forms?', 'Database', 'Medium', 'Software Engineer', 'Technical', 'Normalization organizes data to reduce redundancy. 1NF eliminates repeating groups, 2NF removes partial dependencies, 3NF removes transitive dependencies. BCNF is a stricter form of 3NF.', 'normalization, 1NF, 2NF, 3NF, BCNF, redundancy, dependencies'),
('Explain ACID properties in database transactions.', 'Database', 'Hard', 'Backend Developer', 'Technical', 'Atomicity ensures all-or-nothing execution. Consistency maintains data integrity. Isolation prevents concurrent transaction interference. Durability guarantees committed data persists.', 'ACID, atomicity, consistency, isolation, durability, transactions'),

-- Data Structures & Algorithms
('Explain the time complexity of common sorting algorithms.', 'Algorithms', 'Medium', 'Software Engineer', 'Technical', 'Bubble/Selection/Insertion: O(n²). Merge Sort: O(n log n) guaranteed. Quick Sort: O(n log n) average, O(n²) worst. Heap Sort: O(n log n). Counting/Radix: O(n+k) for bounded integers.', 'time complexity, O(n²), O(n log n), merge sort, quick sort, comparison-based'),
('What is dynamic programming and when would you use it?', 'Algorithms', 'Hard', 'Software Engineer', 'Technical', 'Dynamic programming solves problems by breaking them into overlapping subproblems and storing solutions (memoization/tabulation). Used when a problem has optimal substructure and overlapping subproblems.', 'dynamic programming, memoization, tabulation, optimal substructure, overlapping subproblems'),
('Explain the difference between BFS and DFS and their use cases.', 'Data Structures', 'Medium', 'Software Engineer', 'Technical', 'BFS explores level by level using a queue—good for shortest path in unweighted graphs. DFS explores depth-first using a stack/recursion—good for topological sorting and cycle detection.', 'BFS, DFS, queue, stack, shortest path, topological sort, cycle detection'),
('What is a hash table and how does it handle collisions?', 'Data Structures', 'Easy', 'Software Engineer', 'Technical', 'A hash table maps keys to values using a hash function. Collisions (different keys mapping to the same index) are handled via chaining (linked lists) or open addressing (probing).', 'hash table, hash function, collision, chaining, open addressing'),

-- OOP
('Explain the four pillars of OOP with examples.', 'OOP', 'Easy', 'Software Engineer', 'Technical', 'Encapsulation bundles data and methods. Abstraction hides complexity. Inheritance allows code reuse through parent-child relationships. Polymorphism enables objects to take multiple forms.', 'encapsulation, abstraction, inheritance, polymorphism'),
('What are design patterns? Explain the Singleton and Observer patterns.', 'OOP', 'Hard', 'Software Engineer', 'Technical', 'Design patterns are reusable solutions to common problems. Singleton ensures a class has one instance. Observer defines a one-to-many dependency so dependents are notified of state changes.', 'design patterns, Singleton, Observer, creational, behavioral'),

-- Machine Learning
('Explain the difference between supervised and unsupervised learning.', 'Machine Learning', 'Easy', 'Data Scientist', 'Technical', 'Supervised learning uses labeled data to learn input-output mappings (classification, regression). Unsupervised learning finds patterns in unlabeled data (clustering, dimensionality reduction).', 'supervised, unsupervised, labeled data, classification, clustering'),
('What is overfitting and how do you prevent it?', 'Machine Learning', 'Medium', 'Data Scientist', 'Technical', 'Overfitting occurs when a model memorizes training data and performs poorly on unseen data. Prevention techniques include cross-validation, regularization, dropout, early stopping, and more training data.', 'overfitting, cross-validation, regularization, dropout, early stopping, generalization'),
('Explain the bias-variance tradeoff in machine learning.', 'Machine Learning', 'Hard', 'Data Scientist', 'Technical', 'Bias is error from simplifying assumptions (underfitting). Variance is error from sensitivity to training data (overfitting). The tradeoff is finding model complexity that minimizes total error.', 'bias, variance, underfitting, overfitting, model complexity, total error'),
('What is anomaly detection and what algorithms are used for it?', 'Machine Learning', 'Medium', 'Data Scientist', 'Technical', 'Anomaly detection identifies data points that deviate significantly from normal patterns. Algorithms include Isolation Forest, One-Class SVM, Autoencoders, and statistical methods like Z-score.', 'anomaly detection, Isolation Forest, One-Class SVM, Autoencoder, Z-score'),

-- IoT
('What is IoT and what are its key components?', 'IoT', 'Easy', 'IoT Engineer', 'Technical', 'IoT (Internet of Things) connects physical devices to the internet. Key components include sensors, actuators, microcontrollers, communication protocols, gateways, and cloud platforms.', 'IoT, sensors, actuators, microcontrollers, communication protocols, gateway'),
('Explain the role of ESP32 in IoT applications.', 'IoT', 'Medium', 'IoT Engineer', 'Technical', 'ESP32 is a low-cost microcontroller with built-in WiFi and Bluetooth. It supports GPIO, ADC, SPI, I2C, and is widely used for sensor data collection, actuator control, and wireless communication in IoT.', 'ESP32, WiFi, Bluetooth, GPIO, sensors, microcontroller, wireless'),
('What communication protocols are commonly used in IoT systems?', 'IoT', 'Medium', 'IoT Engineer', 'Technical', 'Common IoT protocols include MQTT (lightweight pub/sub), HTTP/REST (request-response), CoAP (constrained devices), ESP-NOW (peer-to-peer), WebSocket (real-time), and BLE (short-range).', 'MQTT, HTTP, CoAP, ESP-NOW, WebSocket, BLE, pub/sub'),
('How would you design a real-time sensor monitoring system?', 'IoT', 'Hard', 'IoT Engineer', 'Technical', 'Use sensor nodes (ESP32) to collect data, wireless protocols (ESP-NOW/MQTT) for communication, a gateway for aggregation, cloud/Firebase for storage, and a dashboard for real-time visualization with alerting.', 'sensor nodes, ESP32, MQTT, gateway, Firebase, real-time, alerting'),

-- Blockchain
('What is blockchain and how does it ensure data integrity?', 'Blockchain', 'Easy', 'Software Engineer', 'Technical', 'Blockchain is a distributed, immutable ledger where each block contains a hash of the previous block, creating a chain. Tampering with one block invalidates all subsequent blocks, ensuring integrity.', 'distributed ledger, immutable, hash chain, data integrity, blocks'),
('Explain consensus mechanisms in blockchain.', 'Blockchain', 'Hard', 'Software Engineer', 'Technical', 'Consensus mechanisms ensure agreement in distributed networks. Proof of Work requires computational puzzles. Proof of Stake selects validators based on token holdings. Others include DPoS and PBFT.', 'consensus, Proof of Work, Proof of Stake, validators, distributed'),

-- Cloud Computing
('What are the differences between IaaS, PaaS, and SaaS?', 'Cloud Computing', 'Easy', 'DevOps Engineer', 'Technical', 'IaaS provides virtual infrastructure (AWS EC2). PaaS provides a platform for app deployment (Heroku). SaaS provides ready-to-use software (Gmail). Each abstracts more of the underlying infrastructure.', 'IaaS, PaaS, SaaS, infrastructure, platform, abstraction'),
('What is containerization and how does Docker work?', 'Cloud Computing', 'Medium', 'DevOps Engineer', 'Technical', 'Containerization packages applications with their dependencies into isolated containers. Docker uses images (blueprints), containers (running instances), and registries. It ensures consistent environments.', 'containerization, Docker, images, containers, isolation, consistency'),

-- Operating Systems
('Explain process vs thread and when to use each.', 'Operating Systems', 'Medium', 'Software Engineer', 'Technical', 'A process has its own memory space and is isolated. Threads share the process memory and are lighter. Use processes for isolation and threads for concurrent tasks within the same application.', 'process, thread, memory space, isolation, concurrency, shared memory'),
('What is deadlock and how can it be prevented?', 'Operating Systems', 'Hard', 'Software Engineer', 'Technical', 'Deadlock occurs when processes hold resources and wait for others in a circular chain. Prevention: break mutual exclusion, hold-and-wait, no preemption, or circular wait (Coffman conditions).', 'deadlock, circular wait, mutual exclusion, Coffman conditions, prevention'),

-- Computer Networks
('Explain the OSI model and its layers.', 'Computer Networks', 'Medium', 'Software Engineer', 'Technical', 'The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation, Application. Each layer provides specific functionality and communicates with adjacent layers.', 'OSI model, layers, Physical, Network, Transport, Application'),
('What is the difference between TCP and UDP?', 'Computer Networks', 'Easy', 'Software Engineer', 'Technical', 'TCP is connection-oriented, reliable, and ensures ordered delivery with flow control. UDP is connectionless, faster, and used for real-time applications where some data loss is acceptable.', 'TCP, UDP, connection-oriented, connectionless, reliability, real-time'),

-- System Design
('How would you design a URL shortening service?', 'System Design', 'Hard', 'Software Engineer', 'Technical', 'Use a hash/counter to generate short codes, store URL mappings in a database with caching (Redis). Handle 301/302 redirects, consider rate limiting, analytics, and horizontal scaling with load balancers.', 'URL shortening, hashing, database, caching, redirects, scaling'),

-- Sensor Fusion / Edge Computing
('What is sensor fusion and why is it important?', 'IoT', 'Medium', 'IoT Engineer', 'Technical', 'Sensor fusion combines data from multiple sensors to produce more accurate and reliable information than individual sensors alone. Techniques include weighted averaging, Kalman filtering, and complementary filtering.', 'sensor fusion, weighted averaging, Kalman filter, multi-sensor, accuracy'),
('What is edge computing and how does it differ from cloud computing?', 'Cloud Computing', 'Medium', 'IoT Engineer', 'Technical', 'Edge computing processes data near the source (sensors/devices) rather than sending everything to the cloud. It reduces latency, bandwidth usage, and enables real-time decision making for IoT applications.', 'edge computing, latency, bandwidth, real-time, IoT, local processing')
ON CONFLICT DO NOTHING;
